head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/elw_recv_common.js");
scwin.vScrenID = "ULDSTF05923.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.TR_JOB;
scwin.vBzProcsNo;
scwin.vIsurCd;
scwin.vSecugrpID = SECUGRP_ID_EW; //(elw)메뉴단에서 파라미터로 받자..
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_SearchNm); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.vSecugrpID;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_SearchCd.setValue(arrPar[0].ISU_CD);
        txb_SearchNm.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        scwin.fn_read_sync(txb_SearchCd.getValue());
    }
};
scwin.fn_SetInstCdComboCode = function() {
    dts_INST_CD.DataID = "/CodeAction.do?method=listInstCd&For=";
    dts_INST_CD.Reset();
    dts_LEADCOM_MBR_NO.DataID = "/CodeAction.do?method=listLeadCom&For=";
    dts_LEADCOM_MBR_NO.Reset();
};
scwin.fn_read_sync = function() {
    var url;
    url = "/IssueBook.do?method=readIssueBook&inputMessageId=LISTING_ISUBOOK_SEARCH_OUT";
    url += "&SECUGRP_ID=" + scwin.vSecugrpID;
    url += "&P_KEY=" + txb_SearchCd.getValue();
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.Reset();
    url = "/IssueBook.do?method=readLpMbrNoIssueBook&inputMessageId=LISTING_ISUBOOK_SEARCH_OUT";
    url += "&P_KEY=" + txb_SearchCd.getValue();
    dts_LP.DataID = encodeURI(url);
    dts_LP.Reset();
    url = "/IssueBook.do?method=readUlyIssueBook&inputMessageId=LISTING_ISUBOOK_SEARCH_OUT";
    url += "&P_KEY=" + txb_SearchCd.getValue();
    dts_UlyIsu.DataID = encodeURI(url);
    dts_UlyIsu.Reset();
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    //if (! dts_Isu.IsUpdated) {
    //fn_alertNoUpdate() ;return false;
    //}

    return true;
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);

        //alert("[bz_procs_no]"+bz_procs_no);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.fn_trs(TR_JOB_UPDATE);
        }
    }
};
scwin.fn_trs = function(trsIdx) {
    var vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.TR_JOB == "I") vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.TR_JOB == "U") vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;

    else if (scwin.TR_JOB == "D") vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs_Save.Action = $c.lc.fn_encodeNSession("/IssueBook.do?method=updateIssueBook&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Isu)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",SECUGRP_ID=" + scwin.vSecugrpID + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISUR_CD=" + scwin.vIsurCd + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_309;
    trs_Save.Post();
};
scwin.img_ISU_CD_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsuCd;
    scwin.fn_SetPar = fn_SetParIsuCd;
    $c.lc.fn_PopFindIsu(scwin.vSecugrpID);
};
scwin.img_PAY_DD_onclick = function() {
    popUpCalendar2(edt_PAY_DD);
};
scwin.img_SUBS_DD_onclick = function() {
    popUpCalendar2(edt_SUBS_DD);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.dts_UlyIsu_OnLoadError = function() {
    $c.stf.alert_error(dts_UlyIsu);
};
scwin.dts_LP_OnLoadError = function() {
    $c.stf.alert_error(dts_LP);
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_read_sync();
};
scwin.btn_Update_onclick = function() {
    scwin.fn_update();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    $c.elw.fn_searchCode();
    scwin.fn_SetInstCdComboCode();
    //	dts_UDWRT_INST_CD.DataID = "/CodeAction.do?method=listInstCd&For=";
    //	dts_UDWRT_INST_CD.Reset();
    $c.stf.CopyDataSet(dts_INST_CD, dts_UDWRT_INST_CD);
    $c.stf.CopyDataSet(dts_INST_CD, dts_PAY_BK_INST_CD);
    $c.stf.CopyDataSet(dts_INST_CD, dts_BZAGNT_INST_CD);
    $c.stf.CopyDataSet(dts_INST_CD, dts_DEPO_INST_CD);
};
